  hero_tags = '[{"en":"Machine Learning","ar":"تعلّم الآلة"},{"en":"Deep Learning","ar":"التعلّم العميق"},{"en":"Data Science","ar":"علم البيانات"},{"en":"Python","ar":"بايثون"},{"en":"Full-Stack Development","ar":"تطوير الويب المتكامل"},{"en":"Flutter","ar":"Flutter"},{"en":"EdTech","ar":"التقنية التعليمية"}]'::jsonb,
  about_title = '{"en":"Hi, I’m Layan","ar":"أهلاً، أنا ليان"}'::jsonb,
  about_story = '{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I’m a Computer Science graduate from Qatar University (Class of 2026) who loves turning ideas into products people actually use — from machine-learning models to real-time mobile apps."}]},{"type":"paragraph","content":[{"type":"text","text":"My senior capstone, "},{"type":"text","text":"Eventura","marks":[{"type":"bold"}]},{"type":"text","text":", taught me what it takes to ship: I built the Flutter app’s backend integration on Supabase — real-time channels, row-level security, database triggers and cron jobs, GPS geofencing and a context-aware notification system — and coordinated it with a web dashboard built by my teammates."}]},{"type":"paragraph","content":[{"type":"text","text":"On the AI side, I’ve built ML pipelines on 16,000+ records, reached 99% accuracy classifying brain-tumor MRI scans with transfer learning, and taken part in research programs at the Qatar University Young Scientists Center."}]},{"type":"paragraph","content":[{"type":"text","text":"I care about bilingual, accessible design (Arabic and English, full RTL), clear communication, and building things that serve a community — like "},{"type":"text","text":"Tafheem","marks":[{"type":"bold"}]},{"type":"text","text":", a Qur’anic reflection platform where I lead development."}]},{"type":"paragraph","content":[{"type":"text","text":"Right now I’m building the web platform and interactive learning games for "},{"type":"text","text":"Shatharat Educational Training Center","marks":[{"type":"bold"}]},{"type":"text","text":", and interning with the IT department at Al Arqam Academy for Girls."}]}]},"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"تخرّجت في علوم الحاسب من جامعة قطر (دفعة 2026)، وأحب تحويل الأفكار إلى منتجات يستخدمها الناس فعلاً — من نماذج تعلّم الآلة إلى تطبيقات الجوال التي تعمل في الوقت الفعلي."}]},{"type":"paragraph","content":[{"type":"text","text":"علّمني مشروع التخرج "},{"type":"text","text":"إيفنتورا","marks":[{"type":"bold"}]},{"type":"text","text":" ما يتطلبه إطلاق منتج حقيقي: بنيت تكامل تطبيق Flutter مع Supabase — القنوات اللحظية، وأمان مستوى الصفوف، والمشغّلات والمهام المجدولة في قاعدة البيانات، والسياج الجغرافي عبر GPS، ونظام إشعارات ذكي — ونسّقته مع لوحة تحكم الويب التي بناها زملائي."}]},{"type":"paragraph","content":[{"type":"text","text":"وفي مجال الذكاء الاصطناعي، بنيت مسارات تعلّم آلة على أكثر من 16,000 سجل، ووصلت إلى دقة 99% في تصنيف صور أورام الدماغ باستخدام التعلّم بالنقل، وشاركت في برامج بحثية في مركز جامعة قطر للعلماء الشباب."}]},{"type":"paragraph","content":[{"type":"text","text":"أهتم بالتصميم ثنائي اللغة وسهل الوصول (العربية والإنجليزية مع دعم كامل للاتجاه من اليمين لليسار)، وبالتواصل الواضح، وببناء ما يخدم المجتمع — مثل "},{"type":"text","text":"تفهيم","marks":[{"type":"bold"}]},{"type":"text","text":"، منصة التدبّر القرآني التي أقود تطويرها."}]},{"type":"paragraph","content":[{"type":"text","text":"أعمل حالياً على بناء المنصة الإلكترونية والألعاب التعليمية التفاعلية لـ"},{"type":"text","text":"مركز شذرات للتدريب التربوي","marks":[{"type":"bold"}]},{"type":"text","text":"، وأتدرّب في قسم تقنية المعلومات بأكاديمية الأرقم للبنات."}]}]}}'::jsonb,
  interests = '[{"icon":"brain","label":{"en":"Machine learning","ar":"تعلّم الآلة"}},{"icon":"smartphone","label":{"en":"Mobile apps","ar":"تطبيقات الجوال"}},{"icon":"map","label":{"en":"Geospatial data","ar":"البيانات الجغرافية"}},{"icon":"gamepad-2","label":{"en":"Learning games","ar":"الألعاب التعليمية"}},{"icon":"languages","label":{"en":"Bilingual design","ar":"التصميم ثنائي اللغة"}},{"icon":"book-open","label":{"en":"Teaching Arabic","ar":"تعليم العربية"}}]'::jsonb,
  fun_facts = '[{"emoji":"🎤","text":{"en":"I helped organize Qatar University’s AI Week 2025.","ar":"شاركت في تنظيم أسبوع الذكاء الاصطناعي 2025 في جامعة قطر."}},{"emoji":"📚","text":{"en":"I completed Iqra teacher training for teaching Arabic to native and non-native speakers.","ar":"أتممت دورة تأهيل المعلمين لمنهاج اقرأ لتعليم العربية للناطقين بها وبغيرها."}},{"emoji":"💬","text":{"en":"I took part in QU’s first illustrated story marathon (ComicsThon 2026).","ar":"شاركت في النسخة الأولى من ماراثون القصص المصورة (كوميكس ثون 2026)."}},{"emoji":"🎮","text":{"en":"I design interactive story games that teach children skills like managing anger.","ar":"أصمّم ألعاباً قصصية تفاعلية تعلّم الأطفال مهارات مثل إدارة الغضب."}},{"emoji":"🇹🇷","text":{"en":"Arabic is my native language, I work in English, and I’m learning Turkish (A1, TÖMER).","ar":"العربية لغتي الأم، وأعمل بالإنجليزية، وأتعلّم التركية (المستوى A1، تومر)."}}]'::jsonb,
  stats = '[{"value":15,"suffix":"+","label":{"en":"Projects shipped","ar":"مشروعاً منجزاً"}},{"value":500,"suffix":"","label":{"en":"Concurrent users tested on Eventura","ar":"مستخدم متزامن في اختبار إيفنتورا"}},{"value":99,"suffix":"%","label":{"en":"Brain-tumor classification accuracy","ar":"دقة تصنيف أورام الدماغ"}},{"value":3,"suffix":"","label":{"en":"Research internships","ar":"تدريبات بحثية"}}]'::jsonb,
  contact_email = 'alwattarlayan@gmail.com',
  contact_intro = '{"en":"Have a role, a project, or an idea you’d like to build together? I’d love to hear from you.","ar":"هل لديك فرصة عمل أو مشروع أو فكرة نبنيها معاً؟ يسعدني تواصلك."}'::jsonb,
  seo_title = '{"en":"Layan Alwattar — AI/ML & Software Engineer","ar":"ليان الوتار — تعلّم الآلة وهندسة البرمجيات"}'::jsonb,
