values (md5('project:eventura')::uuid, 'eventura', '{"en":"Eventura — Smart Event Management","ar":"إيفنتورا — إدارة الفعاليات الذكية"}'::jsonb, '{"en":"Senior Capstone · Qatar University","ar":"مشروع التخرج · جامعة قطر"}'::jsonb, '{"en":"A web + mobile event platform with QR check-ins under 3 seconds, GPS geofencing, gamified booth challenges and live analytics — load-tested with 500 concurrent users.","ar":"منصة فعاليات للويب والجوال بتسجيل حضور عبر QR في أقل من 3 ثوانٍ، وسياج جغرافي، وتحديات تفاعلية للأجنحة، وتحليلات لحظية — اختُبرت مع 500 مستخدم متزامن."}'::jsonb,
  '{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Eventura is a modular, cloud-backed event management system for booth-based events — conferences, exhibitions and university expos. Organizers and exhibitors use a web dashboard; visitors use a bilingual (EN/AR) Flutter mobile app. Both share one real-time Supabase backend."}]},{"type":"paragraph","content":[{"type":"text","text":"Built by a team of four (Layan Alwattar, Amna Osman, Reem Aladbi, Khawlah Daraan), supervised by Dr. Khaled Shaban and Dr. Saeed Salem."}]}]},"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"إيفنتورا نظام معياري سحابي لإدارة الفعاليات القائمة على الأجنحة — المؤتمرات والمعارض ومعارض الجامعات. يستخدم المنظّمون والعارضون لوحة تحكم على الويب، ويستخدم الزوّار تطبيق جوال ثنائي اللغة مبنياً بـ Flutter، ويتشارك الجميع خلفية Supabase واحدة تعمل لحظياً."}]},{"type":"paragraph","content":[{"type":"text","text":"نفّذه فريق من أربع طالبات (ليان الوتار، آمنة عثمان، ريم العدبي، خولة دعران) بإشراف د. خالد شعبان ود. سعيد سالم."}]}]}}'::jsonb, '{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Event platforms tend to be either rigid or complex and costly. Organizers face:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Long check-in queues and paper sign-ups"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fragmented tools for registration, badges and surveys"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No real-time view of who is attending, where, and when"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Low attendee engagement during long events"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"تميل منصات الفعاليات إلى أن تكون إما جامدة أو معقدة ومكلفة. ويواجه المنظّمون:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"طوابير تسجيل طويلة وأوراق تسجيل يدوية"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"أدوات متفرقة للتسجيل والشارات والاستبيانات"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"غياب الرؤية اللحظية لمن يحضر وأين ومتى"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ضعف تفاعل الحضور خلال الفعاليات الطويلة"}]}]}]}]}}'::jsonb, '{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I worked on the Flutter mobile app with my teammate Reem, focusing on the backend and integration side:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Supabase in depth: schema design, row-level security, real-time channels that push database changes straight into the UI"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Database functions, triggers and scheduled cron jobs for waitlists, event status updates and auto-checkout"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Camera-based QR scanning and QR generation, GPS and geofencing"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A context-aware notification system reacting to geofence transitions, inactivity timers and user roles"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Full Arabic/English support with RTL, plus light and dark themes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Custom SMTP for transactional email and shared API contracts with the web team"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Smart notifications"}]},{"type":"paragraph","content":[{"type":"text","text":"Six types of in-app notification, delivered in real time over Supabase channels with a sound alert and a badge on the bell icon:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Event starting:","marks":[{"type":"bold"}]},{"type":"text","text":" an event you joined is about to begin; tap to open it"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nearby event:","marks":[{"type":"bold"}]},{"type":"text","text":" you walked into an event’s geofence, so you discover events you didn’t know about"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Waitlist open:","marks":[{"type":"bold"}]},{"type":"text","text":" a spot opened on a full event you RSVPed to"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Still here?:","marks":[{"type":"bold"}]},{"type":"text","text":" after 5 hours without activity, choose “Still here” (resets the timer) or “Check me out”"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Auto-checkout:","marks":[{"type":"bold"}]},{"type":"text","text":" confirms you were checked out after leaving the geofence or not answering the prompt"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"General:","marks":[{"type":"bold"}]},{"type":"text","text":" welcomes, system messages and updates"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Each one opens its event, can be marked as read individually, or cleared with “Mark all read”."}]}]},"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"عملت على تطبيق الجوال المبني بـ Flutter مع زميلتي ريم، مع التركيز على جانب الخلفية والتكامل:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Supabase بعمق: تصميم المخطط، وأمان مستوى الصفوف، والقنوات اللحظية التي تنقل تغييرات قاعدة البيانات مباشرة إلى الواجهة"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"دوال ومشغّلات ومهام مجدولة لقوائم الانتظار وتحديث حالة الفعاليات والخروج التلقائي"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"مسح رموز QR بالكاميرا وتوليدها، وGPS والسياج الجغرافي"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"نظام إشعارات ذكي يستجيب لدخول النطاقات الجغرافية ومؤقتات الخمول وأدوار المستخدمين"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"دعم كامل للعربية والإنجليزية مع الاتجاه من اليمين لليسار، ووضعان فاتح وداكن"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"بريد SMTP مخصص وعقود واجهات برمجية مشتركة مع فريق الويب"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"الإشعارات الذكية"}]},{"type":"paragraph","content":[{"type":"text","text":"ستة أنواع من الإشعارات داخل التطبيق، تصل لحظياً عبر قنوات Supabase مع تنبيه صوتي وشارة على أيقونة الجرس:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"بدء الفعالية:","marks":[{"type":"bold"}]},{"type":"text","text":" فعالية سجّلت فيها على وشك البدء؛ اضغط لفتحها"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"فعالية قريبة:","marks":[{"type":"bold"}]},{"type":"text","text":" دخلت النطاق الجغرافي لفعالية، فتكتشف فعاليات لم تكن تعرفها"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"مقعد متاح:","marks":[{"type":"bold"}]},{"type":"text","text":" توفّر مكان في فعالية ممتلئة كنت على قائمة انتظارها"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"هل ما زلت هنا؟:","marks":[{"type":"bold"}]},{"type":"text","text":" بعد 5 ساعات دون نشاط، اختر «ما زلت هنا» (يعيد ضبط المؤقت) أو «سجّل خروجي»"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"خروج تلقائي:","marks":[{"type":"bold"}]},{"type":"text","text":" تأكيد تسجيل خروجك بعد مغادرة النطاق أو عدم الرد على التنبيه"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"عام:","marks":[{"type":"bold"}]},{"type":"text","text":" رسائل الترحيب والنظام والتحديثات"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"يفتح كل إشعار فعاليته، ويمكن تعليمه كمقروء منفرداً أو مسح الجميع بخيار «تعليم الكل كمقروء»."}]}]}}'::jsonb, '{"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"QR scans respond within "},{"type":"text","text":"3 seconds","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Supports "},{"type":"text","text":"500 concurrent users","marks":[{"type":"bold"}]},{"type":"text","text":" without noticeable degradation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"New users completed registration and check-in within minutes, without training"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"85%+","marks":[{"type":"bold"}]},{"type":"text","text":" positive rating in user testing"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Live heatmaps, hour-by-hour engagement charts, competition judging and one-click PDF reports for organizers"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"استجابة مسح QR خلال "},{"type":"text","text":"3 ثوانٍ","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"دعم "},{"type":"text","text":"500 مستخدم متزامن","marks":[{