values (md5('project:tafheem')::uuid, 'tafheem', '{"en":"Tafheem — Qur’anic Reflection Platform","ar":"تفهيم — منصة التدبّر القرآني"}'::jsonb, '{"en":"Production app · Lead Developer","ar":"منصة منشورة · قائدة التطوير"}'::jsonb, '{"en":"A web platform for deeper reflection (tadabbur) on the Qur’an: a word-by-word linguistic study tool, a private/public reflection journal and moderated community features. I own the architecture and backend.","ar":"منصة ويب للتدبّر العميق في القرآن الكريم: أداة لدراسة الكلمات لغوياً كلمةً كلمة، ودفتر تأملات خاص وعام، ومساحة مجتمعية تخضع للإشراف. أتولى البنية التقنية والخلفية."}'::jsonb,
  '{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tafheem helps people engage in deeper, more intentional reflection on the Qur’an. It is built around an intentional "},{"type":"text","text":"“anti-social-media” philosophy","marks":[{"type":"bold"}]},{"type":"text","text":": no likes, no algorithms and no engagement metrics."}]},{"type":"paragraph","content":[{"type":"text","text":"As Lead Developer, I own the technical architecture and backend for Phase 1 (MVP), lead technical decisions (stack, hosting constraints, Arabic/RTL text support), review code and hand designs over to the front-end developer."}]}]},"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"تساعد تفهيم المستخدمين على تدبّر القرآن الكريم بعمق وقصد. وقد بُنيت على "},{"type":"text","text":"فلسفة مضادة لوسائل التواصل","marks":[{"type":"bold"}]},{"type":"text","text":": لا إعجابات ولا خوارزميات ولا مقاييس تفاعل."}]},{"type":"paragraph","content":[{"type":"text","text":"بصفتي قائدة التطوير، أتولى البنية التقنية والخلفية للمرحلة الأولى (MVP)، وأقود القرارات التقنية (اختيار التقنيات وقيود الاستضافة ودعم العربية والكتابة من اليمين لليسار)، وأراجع الشيفرة وأسلّم التصاميم لمطوّر الواجهة."}]}]}}'::jsonb, '{"en":null,"ar":null}'::jsonb, '{"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Designed the system architecture and the MySQL schema"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Built the Node.js/Express REST API"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"JWT authentication with role-based access control (User, Moderator, Admin)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Integrated the Quran.com API for Qur’anic text and word-level data"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Structured the data layer for the Quranic Arabic Corpus and Lane’s Lexicon, behind the tap-a-word linguistic feature"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deployed on Hostinger behind Cloudflare’s CDN"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تصميم بنية النظام ومخطط قاعدة بيانات MySQL"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"بناء واجهة REST باستخدام Node.js وExpress"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"مصادقة JWT مع صلاحيات حسب الدور (مستخدم، مشرف، مدير)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"التكامل مع واجهة Quran.com لنص القرآن وبيانات الكلمات"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"هيكلة طبقة البيانات لمدوّنة القرآن العربية ومعجم لين، لخدمة ميزة الضغط على الكلمة لمعرفة معناها"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"النشر على Hostinger خلف شبكة Cloudflare"}]}]}]}]}}'::jsonb, '{"en":null,"ar":null}'::jsonb, '{"en":null,"ar":null}'::jsonb,
