values (md5('project:shatharat')::uuid, 'shatharat', '{"en":"Shatharat — Training Center Website & Platform","ar":"شذرات — موقع ومنصة مركز التدريب"}'::jsonb, '{"en":"Software Developer & EdTech Lead","ar":"مطوّرة برمجيات وقائدة التقنية التعليمية"}'::jsonb, '{"en":"The official website of Shatharat Educational Training Center (shatharat.qa), which I keep developing and improving, and the course-management system that comes next.","ar":"الموقع الرسمي لمركز شذرات للتدريب التربوي (shatharat.qa) الذي أواصل تطويره وتحسينه، ونظام إدارة الدورات الذي يأتي بعده."}'::jsonb,
  '{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I’m the center’s developer: I built and launched its website on a Qatari .qa domain, behind Cloudflare, with a secure Supabase cloud database. The site introduces the center and its achievements and lets interested families register safely. Visitors to the "},{"type":"text","text":"Aqwamu Qeela exhibition","marks":[{"type":"bold"}]},{"type":"text","text":" discover the center through it."}]},{"type":"paragraph","content":[{"type":"text","text":"The website is live and I keep developing and improving it. The learning games I built for the exhibition are a separate, finished project."}]}]},"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"أعمل مطوّرةً للمركز: بنيت موقعه وأطلقته على نطاق قطري ‎.qa خلف Cloudflare مع قاعدة بيانات سحابية آمنة على Supabase. يعرّف الموقع بالمركز وإنجازاته ويتيح للأسر المهتمة التسجيل بأمان، ويتعرّف زوّار "},{"type":"text","text":"معرض أقوم قيلا","marks":[{"type":"bold"}]},{"type":"text","text":" على المركز من خلاله."}]},{"type":"paragraph","content":[{"type":"text","text":"الموقع منشور وأواصل تطويره وتحسينه، أما الألعاب التعليمية التي بنيتها للمعرض فهي مشروع مستقل مكتمل."}]}]}}'::jsonb, '{"en":null,"ar":null}'::jsonb, '{"en":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Course-management system (planned in phases)"}]},{"type":"paragraph","content":[{"type":"text","text":"I ran a requirements survey with the center’s team and turned it into a phased plan:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Phase 1:","marks":[{"type":"bold"}]},{"type":"text","text":" the public website — programs, schedules, trainers, news and articles"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Phase 2:","marks":[{"type":"bold"}]},{"type":"text","text":" online registration, a database of families, students and courses, an admin dashboard, Excel exports and fee tracking"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Phase 3:","marks":[{"type":"bold"}]},{"type":"text","text":" parent and trainer accounts, attendance and achievement portfolios for every student, reminders, and later a mobile app"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"نظام إدارة الدورات (على مراحل)"}]},{"type":"paragraph","content":[{"type":"text","text":"أجريت استبياناً لاحتياجات فريق المركز وحوّلته إلى خطة مرحلية:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"المرحلة الأولى:","marks":[{"type":"bold"}]},{"type":"text","text":" الموقع العام — البرامج والمواعيد والمدربات والأخبار والمقالات"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"المرحلة الثانية:","marks":[{"type":"bold"}]},{"type":"text","text":" التسجيل الإلكتروني، وقاعدة بيانات للأهالي والطلاب والدورات، ولوحة تحكم، وتصدير إلى Excel، ومتابعة الرسوم"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"المرحلة الثالثة:","marks":[{"type":"bold"}]},{"type":"text","text":" حسابات للأهالي والمدربات، وملف حضور وإنجاز لكل طالب، وتذكيرات، ثم تطبيق جوال لاحقاً"}]}]}]}]}}'::jsonb, '{"en":null,"ar":null}'::jsonb, '{"en":null,"ar":null}'::jsonb,
