values (md5('project:brain-tumor-classification')::uuid, 'brain-tumor-classification', '{"en":"Brain Tumor Classification","ar":"تصنيف أورام الدماغ"}'::jsonb, '{"en":"Deep Learning · Medical Computer Vision","ar":"التعلّم العميق · الرؤية الحاسوبية الطبية"}'::jsonb, '{"en":"Benchmarked ResNet50, VGG16 and MobileNetV2 with transfer learning to classify brain MRI scans. ResNet50 reached about 99% accuracy.","ar":"مقارنة ResNet50 وVGG16 وMobileNetV2 بالتعلّم بالنقل لتصنيف صور الرنين المغناطيسي للدماغ، ووصل ResNet50 إلى دقة تقارب 99%."}'::jsonb,
  '{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An automated image-classification system that detects and classifies brain tumors in MRI scans by fine-tuning pretrained convolutional networks."}]}]},"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"نظام آلي لاكتشاف أورام الدماغ وتصنيفها في صور الرنين المغناطيسي عبر ضبط شبكات عصبية التفافية مدرّبة مسبقاً."}]}]}}'::jsonb, '{"en":null,"ar":null}'::jsonb, '{"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Preprocessing:","marks":[{"type":"bold"}]},{"type":"text","text":" image standardization, data augmentation against overfitting, label encoding and a train/test split"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Models:","marks":[{"type":"bold"}]},{"type":"text","text":" ResNet50, VGG16 and MobileNetV2 in TensorFlow/Keras"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Evaluation:","marks":[{"type":"bold"}]},{"type":"text","text":" hyperparameter tuning, classification reports, precision/recall and confusion matrices"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"المعالجة المسبقة:","marks":[{"type":"bold"}]},{"type":"text","text":" توحيد الصور، وزيادة البيانات للحد من فرط التخصيص، وترميز التصنيفات، وتقسيم البيانات للتدريب والاختبار"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"النماذج:","marks":[{"type":"bold"}]},{"type":"text","text":" ResNet50 وVGG16 وMobileNetV2 باستخدام TensorFlow/Keras"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"التقييم:","marks":[{"type":"bold"}]},{"type":"text","text":" ضبط المعاملات، وتقارير التصنيف، والدقة والاستدعاء، ومصفوفات الالتباس"}]}]}]}]}}'::jsonb, '{"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"≈99% accuracy","marks":[{"type":"bold"}]},{"type":"text","text":" with ResNet50 on the test set"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"دقة تقارب "},{"type":"text","text":"99%","marks":[{"type":"bold"}]},{"type":"text","text":" باستخدام ResNet50 على بيانات الاختبار"}]}]}]}]}}'::jsonb, '{"en":null,"ar":null}'::jsonb,
