values (md5('project:sadeeq-npc-datathon')::uuid, 'sadeeq-npc-datathon', '{"en":"Sadeeq — Environmental Data for Children","ar":"صديق — بيانات البيئة للأطفال"}'::jsonb, '{"en":"NPC Qatar Datathon 2025 · Team Oxygen","ar":"داتاثون قطر 2025 · فريق أكسجين"}'::jsonb, '{"en":"A playful platform that turns the National Planning Council’s environmental data into child-friendly charts, an interactive map of protected areas and a water-saving game.","ar":"منصة مرحة تحوّل البيانات البيئية للمجلس الوطني للتخطيط إلى رسوم بيانية تناسب الأطفال، وخريطة تفاعلية للمحميات الطبيعية، ولعبة لترشيد المياه."}'::jsonb,
  '{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sadeeq","marks":[{"type":"bold"}]},{"type":"text","text":" (System for Awareness Development and Environmental Education in Qatar) tells the environment’s story to children through simple visuals and games, supporting the targets of Qatar’s Third National Development Strategy."}]},{"type":"paragraph","content":[{"type":"text","text":"Built with Amna Osman and Khawlah Daraan in the Environment track. Our idea was recognized as one of the most creative and unique. After the certificates were handed out, the organizers met privately with our team (and a few other teams) to discuss the idea, and we presented Sadeeq to the people attending."}]}]},"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"صديق","marks":[{"type":"bold"}]},{"type":"text","text":" (نظام لتنمية الوعي والتعليم البيئي في قطر) يروي قصة البيئة للأطفال عبر رسوم بسيطة وألعاب، دعماً لأهداف استراتيجية التنمية الوطنية الثالثة."}]},{"type":"paragraph","content":[{"type":"text","text":"نفّذته مع آمنة عثمان وخولة دعران في مسار البيئة. اعتُبرت فكرتنا من أكثر الأفكار إبداعاً وتميزاً، وبعد تسليم الشهادات التقى المنظّمون بفريقنا (وبعدد من الفرق الأخرى) على انفراد لمناقشة الفكرة، وعرضنا «صديق» على الحضور."}]}]}}'::jsonb, '{"en":null,"ar":null}'::jsonb, '{"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Worked through the NPC’s annual bulletins, monthly data and environmental summaries"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Annual data powers the endangered-species charts; monthly data powers the water-consumption chart"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Natural protected areas from the annual summary drive the interactive map"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Simplified each chart to a few variables so children can read it — more like a game or a show than a lesson"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"دراسة النشرات السنوية والبيانات الشهرية والملخصات البيئية للمجلس الوطني للتخطيط"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"البيانات السنوية تغذّي رسوم الأنواع المهددة، والشهرية تغذّي رسم استهلاك المياه"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"المحميات الطبيعية من الملخص السنوي تشكّل الخريطة التفاعلية"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تبسيط كل رسم إلى متغيرات قليلة ليقرأه الطفل — أقرب إلى لعبة أو عرض منه إلى درس"}]}]}]}]}}'::jsonb, '{"en":null,"ar":null}'::jsonb, '{"en":null,"ar":null}'::jsonb,
  array['Data Analysis', 'Data Visualization', 'UI/UX', 'Gamification']::text[], '/content/sadeeq/welcome.webp', null, null, null,
  null, null, '2025-02-15', '2025-02-20', false,
  false, 'published', 8, now())
