values (md5('project:project-silence')::uuid, 'project-silence', '{"en":"Project S.I.L.E.N.C.E.","ar":"مشروع S.I.L.E.N.C.E."}'::jsonb, '{"en":"AI & Algorithms Competition 2024 · INHA Publication Inc.","ar":"مسابقة الذكاء الاصطناعي والخوارزميات 2024"}'::jsonb, '{"en":"A multi-stage recovery system for a corrupted sentiment-analysis pipeline, combining GPT-2 with depth-first search, plus an analysis of bias in pretrained classifiers.","ar":"نظام استعادة متعدد المراحل لمسار تحليل مشاعر تعرّض للتلف، يجمع GPT-2 مع البحث بالعمق أولاً، مع تحليل للتحيّز في المصنّفات المدرّبة مسبقاً."}'::jsonb,
  '{"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Designed a recovery system that uses GPT-2 language models with depth-first search to reconstruct corrupted sentiment data"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Identified, measured and mitigated bias in pretrained sentiment classifiers"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تصميم نظام استعادة يستخدم نماذج GPT-2 مع البحث بالعمق أولاً لإعادة بناء بيانات المشاعر التالفة"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"رصد التحيّز في مصنّفات المشاعر المدرّبة مسبقاً وقياسه والحد منه"}]}]}]}]}}'::jsonb, '{"en":null,"ar":null}'::jsonb, '{"en":null,"ar":null}'::jsonb, '{"en":null,"ar":null}'::jsonb, '{"en":null,"ar":null}'::jsonb,
