values (md5('project:hia-passenger-survey')::uuid, 'hia-passenger-survey', '{"en":"Airport Passengers at Hamad International Airport","ar":"المسافرون في مطار حمد الدولي"}'::jsonb, '{"en":"Research program participant · SRIP 2024","ar":"مشاركة في برنامج بحثي · 2024"}'::jsonb, '{"en":"Profiles, trip and parking characteristics of arriving and departing passengers, from intercept surveys analyzed in SPSS, with recommendations for airport access.","ar":"خصائص المسافرين القادمين والمغادرين ورحلاتهم واستخدامهم للمواقف، من استبيانات ميدانية حُلّلت بـ SPSS، مع توصيات لتحسين الوصول إلى المطار."}'::jsonb,
  '{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"As a participant in Qatar University’s Summer Research Internship Program, hosted by the Qatar Transportation and Traffic Safety Center (mentor: Eng. Deepti Muley), I studied how travelers reach Hamad International Airport and where they park, using intercept surveys of arriving and departing passengers."}]}]},"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"بصفتي مشاركة في برنامج التدريب البحثي الصيفي لجامعة قطر، الذي استضافه مركز قطر للنقل والسلامة المرورية (بإشراف م. ديبتي مولي)، درست كيف يصل المسافرون إلى مطار حمد الدولي وأين يركنون سياراتهم، من خلال استبيانات ميدانية للقادمين والمغادرين."}]}]}}'::jsonb, '{"en":null,"ar":null}'::jsonb, '{"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reviewed literature on airport passengers’ travel and parking behavior and summarized related papers"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Learned the questionnaire design and data-collection method for both passenger groups"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Coded the dataset and analyzed it in SPSS: descriptive statistics, correlations and ANOVA"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Presented the results on a research poster"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"مراجعة الأدبيات حول سلوك المسافرين في التنقل والمواقف وتلخيص أبحاث ذات صلة"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"فهم تصميم الاستبيان وطريقة جمع البيانات لكلا الفئتين"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ترميز البيانات وتحليلها بـ SPSS: إحصاءات وصفية وارتباطات وANOVA"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"عرض النتائج في ملصق بحثي"}]}]}]}]}}'::jsonb, '{"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Higher-income travelers tend to use personal vehicles to reach the airport"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Average travel time to the airport: about "},{"type":"text","text":"33 minutes","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"75%","marks":[{"type":"bold"}]},{"type":"text","text":" of trips had a single traveler"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"68%","marks":[{"type":"bold"}]},{"type":"text","text":" of departing passengers were visiting their home country"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recommendations: free remote parking with a free shuttle, progressive short-term parking fees, and dedicated taxi lanes"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"يميل المسافرون من ذوي الدخل الأعلى إلى استخدام سياراتهم الخاصة للوصول إلى المطار"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"متوسط زمن الرحلة إلى المطار نحو "},{"type":"text","text":"33 دقيقة","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"75%","marks":[{"type":"bold"}]},{"type":"text","text":" من الرحلات لمسافر واحد"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"68%","marks":[{"type":"bold"}]},{"type":"text","text":" من المغادرين متجهون لزيارة بلدهم الأم"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"التوصيات: مواقف مجانية خارج المطار مع نقل مجاني، وتعرفة تصاعدية للمواقف قصيرة المدى، ومسارات مخصصة لسيارات الأجرة"}]}]}]}]}}'::jsonb, '{"en":null,"ar":null}'::jsonb,
  array['SPSS', 'Excel', 'Descriptive statistics', 'Correlation', 'ANOVA', 'Survey design']::text[], null, null, null, null,
  null, null, '2024-05-26', '2024-06-13', false,
