values (md5('project:road-accidents-qatar')::uuid, 'road-accidents-qatar', '{"en":"Traffic Accidents in Qatar, 2021–2024","ar":"حوادث المرور في قطر 2021–2024"}'::jsonb, '{"en":"Data Cleaning & Exploratory Analysis","ar":"تنظيف البيانات والتحليل الاستكشافي"}'::jsonb, '{"en":"Cleaning and exploring about a million accident records from the Ministry of Interior, with interactive charts of when, where and how severely accidents happen.","ar":"تنظيف قرابة مليون سجل لحوادث المرور من وزارة الداخلية واستكشافها، مع مخططات تفاعلية توضح متى وأين تقع الحوادث ومدى خطورتها."}'::jsonb,
  '{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The dataset comes from Qatar’s Open Data Portal (Ministry of Interior): about 1,000,500 rows and 16 columns covering time, conditions, road type, city, zone and street, driver nationality and birth year, deaths and severity. I translated it from Arabic to English before the analysis."}]}]},"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"البيانات من بوابة البيانات المفتوحة في قطر (وزارة الداخلية): نحو 1,000,500 سجل و16 عموداً تشمل الوقت والظروف ونوع الطريق والمدينة والمنطقة والشارع وجنسية السائق وسنة ميلاده والوفيات ودرجة الخطورة، وقد ترجمتها من العربية إلى الإنجليزية قبل التحليل."}]}]}}'::jsonb, '{"en":null,"ar":null}'::jsonb, '{"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Split train/test "},{"type":"text","text":"before","marks":[{"type":"bold"}]},{"type":"text","text":" imputation to avoid leakage; dropped columns over 60% missing and filled moderate gaps with “UNKNOWN”"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Standardized text and checked for duplicates and synonym categories"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deaths and accident counts are extremely skewed (IQR = 0), so I "},{"type":"text","text":"winsorized at the 99th percentile","marks":[{"type":"bold"}]},{"type":"text","text":" instead of deleting fatal accidents, which are real events, not errors"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Engineered driver age (and flagged underage or anomalous drivers), encoded the hour, one-hot encoded categories and scaled on the training data only"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تقسيم البيانات "},{"type":"text","text":"قبل","marks":[{"type":"bold"}]},{"type":"text","text":" تعويض القيم لتجنب التسرّب، وحذف الأعمدة التي تتجاوز نسبة النقص فيها 60%، وملء النقص المتوسط بقيمة «غير معروف»"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"توحيد النصوص وفحص التكرارات والفئات المترادفة"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"الوفيات وعدد الحوادث شديدة الالتواء (IQR = 0)، لذلك "},{"type":"text","text":"حددت القيم عند المئين 99","marks":[{"type":"bold"}]},{"type":"text","text":" بدلاً من حذف الحوادث المميتة لأنها أحداث حقيقية وليست أخطاء"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"اشتقاق عمر السائق (مع تعليم السائقين دون السن أو الشاذين)، وترميز الساعة والفئات، وتوحيد المقاييس على بيانات التدريب فقط"}]}]}]}]}}'::jsonb, '{"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"825,108","marks":[{"type":"bold"}]},{"type":"text","text":" records from 2021 to 2024; about "},{"type":"text","text":"95.2%","marks":[{"type":"bold"}]},{"type":"text","text":" of accidents with a known severity are “simple”, and 99.9% have no deaths"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Accidents peak between 8 AM and noon, and most drivers involved are 25–44"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Late-night accidents are rarer but "},{"type":"text","text":"far more severe","marks":[{"type":"bold"}]},{"type":"text","text":": around midnight, heavy or fatal injuries are about 7× more common than at 9 AM"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Numeric features barely correlate, so time, zone and road type carry the signal. That is why later modeling should use F1-score rather than accuracy"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"825,108","marks":[{"type":"bold"}]},{"type":"text","text":" سجل من 2021 إلى 2024؛ ونحو "},{"type":"text","text":"95.2%","marks":[{"type":"bold"}]},{"type":"text","text":" من الحوادث المعروفة خطورتها «بسيطة»، و99.9% بلا وفيات"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تبلغ الحوادث ذروتها بين الثامنة صباحاً والظهر، وأغلب السائقين بين 25 و44 عاماً"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"حوادث آخر الليل أقل عدداً لكنها "},{"type":"text","text":"أشد خطورة بكثير","marks":[{"type":"bold"}]},{"type":"text","text":": قرب منتصف الليل تكون الإصابات البليغة أو المميتة أكثر بنحو 7 أضعاف منها في التاسعة صباحاً"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"الخصائص الرقمية ضعيفة الارتباط، والإشارة الحقيقية في الوقت والمنطقة ونوع الطريق، ولذلك يُفضَّل استخدام مقياس F1 بدلاً من الدقة عند النمذجة"}]}]}]}]}}'::jsonb, '{"en":null,"ar":null}'::jsonb,
  array['Python', 'Pandas', 'NumPy', 'Scikit-Learn', 'Matplotlib', 'Seaborn']::text[], null, null, null, null,
  null, null, null, null, false,
  false, 'published', 11, now())
