values (md5('project:kalimati')::uuid, 'kalimati', '{"en":"Kalimati — Language Learning App","ar":"كلماتي — تطبيق لتعلّم اللغات"}'::jsonb, '{"en":"Mobile App · CMPS 312","ar":"تطبيق جوال · CMPS 312"}'::jsonb, '{"en":"An offline-first Flutter app for learning languages through curated vocabulary packages and three mini-games, built with clean architecture and Riverpod.","ar":"تطبيق Flutter يعمل دون اتصال لتعلّم اللغات عبر حزم مفردات منتقاة وثلاث ألعاب مصغّرة، مبني ببنية نظيفة وRiverpod."}'::jsonb,
  '{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kalimati helps learners "},{"type":"text","text":"learn words, play the games and remember more","marks":[{"type":"bold"}]},{"type":"text","text":". Users sign in, then browse and create learning packages organized by language, level and category, with words, definitions, example sentences, and image and video resources. Three mini-games reinforce learning:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Flash cards"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Match the word to its definition"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Unscramble the sentence"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Built by Team G5 (Layan Alwattar, Maryam Bawazir, Reem Aladbi, Sara Alyahri) for CMPS 312 at Qatar University."}]}]},"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"يساعد كلماتي المتعلمين على "},{"type":"text","text":"تعلّم الكلمات واللعب وتذكّر المزيد","marks":[{"type":"bold"}]},{"type":"text","text":". يسجّل المستخدم دخوله ثم يتصفح حزماً تعليمية مصنّفة حسب اللغة والمستوى والفئة وينشئها، وتتضمن كلمات وتعريفات وجملاً وأمثلة وموارد صور وفيديو. وتعزّز ثلاث ألعاب مصغّرة التعلّم:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"البطاقات التعليمية"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"مطابقة الكلمة بتعريفها"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ترتيب الجملة المبعثرة"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"نفّذه الفريق G5 (ليان الوتار، مريم باوزير، ريم العدبي، سارة اليهري) لمقرر CMPS 312 في جامعة قطر."}]}]}}'::jsonb, '{"en":null,"ar":null}'::jsonb, '{"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Feature-first clean architecture (domain, data and presentation layers)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Offline-first local database with Floor ORM + SQLite and seeded sample data"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Riverpod state management and go_router navigation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Full CRUD on packages, words, definitions and sentences"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"بنية نظيفة مقسّمة حسب الميزات (طبقات المجال والبيانات والعرض)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"قاعدة بيانات محلية تعمل دون اتصال باستخدام Floor وSQLite مع بيانات تجريبية"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إدارة الحالة بـ Riverpod والتنقل بـ go_router"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إضافة وتعديل وحذف الحزم والكلمات والتعريفات والجمل"}]}]}]}]}}'::jsonb, '{"en":null,"ar":null}'::jsonb, '{"en":null,"ar":null}'::jsonb,
