-- Analyses, datasets and charts

insert into public.analyses (id, slug, title, summary, insights, cover_url, tools, status, position, published_at)
values (md5('analysis:ai-simulation-tools-higher-education')::uuid, 'ai-simulation-tools-higher-education', '{"en":"AI Simulation Tools in Higher Education: Student Perspectives","ar":"أدوات المحاكاة بالذكاء الاصطناعي في التعليم العالي: وجهات نظر الطلاب"}'::jsonb, '{"en":"A mixed-methods study (SRIP 2026, QU Young Scientists Center) of how undergraduates perceive AI simulation tools — usefulness, problem-solving confidence and engagement.","ar":"دراسة بمنهج مختلط (برنامج التدريب البحثي الصيفي 2026، مركز جامعة قطر للعلماء الشباب) حول نظرة طلاب البكالوريوس إلى أدوات المحاكاة بالذكاء الاصطناعي — الفائدة المدركة والثقة في حل المشكلات والتفاعل."}'::jsonb, '{"en":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Question"}]},{"type":"paragraph","content":[{"type":"text","text":"How do undergraduate students perceive AI simulation tools in higher education — and do perceptions differ across student groups?"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Method"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"15-item questionnaire measuring "},{"type":"text","text":"Perceived Usefulness","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Problem-Solving Confidence","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Engagement & Motivation","marks":[{"type":"bold"}]},{"type":"text","text":" (5 items each)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Undergraduate participants from STEM and non-STEM disciplines: 103 when the poster was made, and the sample keeps growing (150+), plus focus groups with internship students"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Descriptive statistics, Cronbach’s alpha, Spearman correlation, Mann–Whitney U and Kruskal–Wallis tests; thematic analysis of focus groups"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What the reliability analysis shows"}]},{"type":"paragraph","content":[{"type":"text","text":"The chart below is a "},{"type":"text","text":"practice analysis on an early version of the data","marks":[{"type":"bold"}]},{"type":"text","text":", done to learn the method; final numbers will change as responses grow. In that early sample, all three scales showed "},{"type":"text","text":"strong internal consistency","marks":[{"type":"bold"}]},{"type":"text","text":" (α ≥ .87), so each construct can be summarized with a single score. Normality tests (Kolmogorov–Smirnov and Shapiro–Wilk, p < .001) indicated non-normal distributions, which is why the group comparisons use non-parametric tests."}]},{"type":"paragraph","content":[{"type":"text","text":"Co-authored with the SRIP 2026 team under Dr. Jolly Bhadra."}]}]},"ar":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"السؤال"}]},{"type":"paragraph","content":[{"type":"text","text":"كيف ينظر طلاب البكالوريوس إلى أدوات المحاكاة بالذكاء الاصطناعي في التعليم العالي، وهل تختلف هذه النظرة بين فئات الطلاب؟"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"المنهجية"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"استبيان من 15 بنداً يقيس "},{"type":"text","text":"الفائدة المدركة","marks":[{"type":"bold"}]},{"type":"text","text":" و"},{"type":"text","text":"الثقة في حل المشكلات","marks":[{"type":"bold"}]},{"type":"text","text":" و"},{"type":"text","text":"التفاعل والدافعية","marks":[{"type":"bold"}]},{"type":"text","text":" (5 بنود لكل منها)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"مشاركون من طلاب البكالوريوس في تخصصات علمية وغير علمية: 103 عند إعداد الملصق، والعدد مستمر في الازدياد (أكثر من 150)، إضافة إلى مجموعات نقاش مع طلاب التدريب"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إحصاءات وصفية، ومعامل كرونباخ ألفا، وارتباط سبيرمان، واختبارا مان–ويتني وكروسكال–واليس، وتحليل موضوعي لمجموعات النقاش"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"ماذا يُظهر تحليل الثبات"}]},{"type":"paragraph","content":[{"type":"text","text":"المخطط أدناه "},{"type":"text","text":"تحليل تدريبي على نسخة مبكرة من البيانات","marks":[{"type":"bold"}]},{"type":"text","text":" أُجري لتعلّم المنهجية، وستتغير الأرقام النهائية مع ازدياد الردود. في تلك العينة المبكرة أظهرت المقاييس الثلاثة "},{"type":"text","text":"اتساقاً داخلياً قوياً","marks":[{"type":"bold"}]},{"type":"text","text":" (ألفا ≥ 0.87)، ما يسمح بتلخيص كل مقياس بدرجة واحدة. وأشارت اختبارات التوزيع الطبيعي (كولموغوروف–سميرنوف وشابيرو–ويلك، p < .001) إلى توزيعات غير طبيعية، ولذلك استُخدمت اختبارات لا معلمية لمقارنة المجموعات."}]},{"type":"paragraph","content":[{"type":"text","text":"بالمشاركة مع فريق برنامج 2026 بإشراف د. جولي بهادرا."}]}]}}'::jsonb,
  null, array['SPSS', 'Cronbach’s Alpha', 'Spearman', 'Mann–Whitney U', 'Kruskal–Wallis', 'Thematic analysis']::text[], 'published', 0, now())
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, insights = excluded.insights, cover_url = excluded.cover_url, tools = excluded.tools, status = excluded.status, position = excluded.position, published_at = coalesce(public.analyses.published_at, excluded.published_at), created_at = now()
where public.analyses.created_at = public.analyses.updated_at;

