select md5('chart:ai-simulation-tools-higher-education')::uuid, md5('dataset:ai-simulation-tools-higher-education')::uuid, '{"en":"Scale reliability (Cronbach’s α)","ar":"ثبات المقاييس (معامل كرونباخ ألفا)"}'::jsonb, '{"en":"Practice analysis on an early version of the data (n = 87), done to learn the method. Data collection continues (150+ responses), so final values will differ.","ar":"تحليل تدريبي على نسخة مبكرة من البيانات (n = 87) لتعلّم المنهجية. جمع البيانات مستمر (أكثر من 150 رداً)، لذا ستختلف القيم النهائية."}'::jsonb, 'bar',
  'Construct', array['Cronbach alpha']::text[], '{"aggregate":"none","sort":"none","horizontal":true,"xLabel":"","yLabel":""}'::jsonb, id, 'published', 0
from public.analyses where slug = 'ai-simulation-tools-higher-education'
